"""
Data schemas and profile models for the AuditPilot multi-agent audit system.
"""

from typing import Literal
from pydantic import BaseModel, Field


class DataProfile(BaseModel):
    """Structured data profile generated by the intake_agent.

    Captures file validation, double-entry mathematical balance, fiscal period
    boundaries, and trial balance reconciliation status.
    """

    status: Literal["PASSED", "PASSED_WITH_VARIANCE", "FAILED"] = Field(
        ...,
        description=(
            "Status of data intake: 'FAILED' if files are missing, unreadable, or missing columns; "
            "'PASSED_WITH_VARIANCE' if files are structurally valid but reconciliation gaps exist; "
            "'PASSED' if all files are valid and trial balance reconciles with zero discrepancy."
        ),
    )
    failure_reasons: list[str] = Field(
        default_factory=list,
        description="List of specific failure reasons if status is FAILED.",
    )
    row_count: int | None = Field(
        default=None,
        description="Total row count of the general ledger.",
    )
    column_count: int | None = Field(
        default=None,
        description="Number of columns present in the general ledger.",
    )
    total_debit_inr: float | None = Field(
        default=None,
        description="Total debit sum across the general ledger in INR.",
    )
    total_credit_inr: float | None = Field(
        default=None,
        description="Total credit sum across the general ledger in INR.",
    )
    is_balanced: bool | None = Field(
        default=None,
        description="True if total debits equal total credits within 0.01 tolerance.",
    )
    start_date: str | None = Field(
        default=None,
        description="Earliest transaction date found in the general ledger (YYYY-MM-DD).",
    )
    end_date: str | None = Field(
        default=None,
        description="Latest transaction date found in the general ledger (YYYY-MM-DD).",
    )
    trial_balance_reconciled: bool | None = Field(
        default=None,
        description="True if all accounts in trial balance match ledger account totals.",
    )
    trial_balance_gap_inr: float | None = Field(
        default=None,
        description="Total monetary gap between ledger and trial balance across all accounts in INR.",
    )
    flagged_ids: list[str] = Field(
        default_factory=list,
        description="Journal entry IDs identified during intake (e.g. trial balance gap candidates).",
    )
    notes: str = Field(
        ...,
        description="Detailed summary notes explaining validation and reconciliation findings.",
    )


class AnomalyFindings(BaseModel):
    """Structured audit findings generated by anomaly_agent.

    Captures first-digit Benford's Law analysis, duplicate payment detection,
    structured split-payment anomalies, and Sunday round-amount manual postings.
    """

    benford_status: str = Field(
        ...,
        description="Benford's Law conformity status (e.g., 'FLAGGED', 'CONFORMING').",
    )
    benford_chi2: float | None = Field(
        default=None,
        description="Chi-Square goodness-of-fit test statistic.",
    )
    benford_mad: float | None = Field(
        default=None,
        description="Mean Absolute Deviation (MAD) of first-digit distribution.",
    )
    benford_spikes: list[int] = Field(
        default_factory=list,
        description="Digits displaying significant statistical deviation/spikes.",
    )
    duplicate_count: int = Field(
        ...,
        description="Number of duplicate payment transaction entries flagged.",
    )
    duplicate_entry_ids: list[str] = Field(
        default_factory=list,
        description="Entry IDs associated with duplicate payments.",
    )
    duplicate_total_inr: float | None = Field(
        default=None,
        description="Total INR amount exposed to duplicate payments.",
    )
    split_payment_group_count: int = Field(
        ...,
        description="Number of structured split-payment groups detected.",
    )
    split_payment_entry_ids: list[str] = Field(
        default_factory=list,
        description="Entry IDs involved in split payment structuring.",
    )
    split_payment_total_inr: float | None = Field(
        default=None,
        description="Total INR amount across all split-payment transactions.",
    )
    weekend_round_count: int = Field(
        ...,
        description="Number of round-amount entries posted on Sundays.",
    )
    weekend_round_entry_ids: list[str] = Field(
        default_factory=list,
        description="Entry IDs posted on Sundays in round increments.",
    )
    weekend_round_total_inr: float | None = Field(
        default=None,
        description="Total INR amount of Sunday round postings.",
    )
    total_anomalies_flagged: int = Field(
        ...,
        description="Total count of unique anomalous entry IDs flagged by all anomaly checks.",
    )
    flagged_ids: list[str] = Field(
        default_factory=list,
        description="Combined list of all unique flagged entry IDs.",
    )
    notes: str = Field(
        ...,
        description="Detailed forensic summary of statistical and pattern anomalies.",
    )


class VendorFindings(BaseModel):
    """Structured audit findings generated by vendor_agent.

    Captures vendor compliance risks, shared employee-vendor banking records,
    and ghost vendor anomalies (missing/invalid GSTIN or cooling-off breaches).
    """

    ghost_vendor_count: int = Field(
        ...,
        description="Number of suspicious ghost vendors identified.",
    )
    ghost_vendor_ids: list[str] = Field(
        default_factory=list,
        description="Vendor IDs flagged as ghost vendors.",
    )
    shared_account_count: int = Field(
        ...,
        description="Number of vendors sharing bank account details with employees.",
    )
    shared_account_vendor_ids: list[str] = Field(
        default_factory=list,
        description="Vendor IDs sharing bank accounts with employees.",
    )
    shared_account_employee_ids: list[str] = Field(
        default_factory=list,
        description="Employee IDs associated with shared vendor bank accounts.",
    )
    flagged_entry_ids: list[str] = Field(
        default_factory=list,
        description="Ledger entry IDs associated with ghost vendors or shared bank accounts.",
    )
    total_at_risk_inr: float | None = Field(
        default=None,
        description="Total INR disbursed to flagged vendor accounts.",
    )
    flagged_ids: list[str] = Field(
        default_factory=list,
        description="List of all flagged ledger entry IDs.",
    )
    notes: str = Field(
        ...,
        description="Forensic narrative detailing vendor banking conflicts and ghosting risks.",
    )


class RatioFindings(BaseModel):
    """Structured financial ratio findings generated by ratio_agent.

    Evaluates liquidity, profitability, and leverage metrics across 12 monthly periods.
    """

    months_analyzed: int = Field(
        ...,
        description="Number of monthly financial periods analyzed.",
    )
    average_gross_margin: float | None = Field(
        default=None,
        description="Annual average Gross Profit Margin ratio.",
    )
    average_operating_margin: float | None = Field(
        default=None,
        description="Annual average Operating Margin ratio.",
    )
    average_current_ratio: float | None = Field(
        default=None,
        description="Annual average Current Ratio (liquidity).",
    )
    average_debt_to_equity: float | None = Field(
        default=None,
        description="Annual average Debt-to-Equity leverage ratio.",
    )
    liquidity_status: str = Field(
        ...,
        description="Assessment of corporate liquidity (e.g. 'HEALTHY', 'DISTRESSED').",
    )
    solvency_status: str = Field(
        ...,
        description="Assessment of financial leverage and solvency.",
    )
    flagged_months: list[str] = Field(
        default_factory=list,
        description="Months with anomalous ratio spikes or distress (e.g. ['2025-07']).",
    )
    notes: str = Field(
        ...,
        description="Executive summary of financial statement health and trend risks.",
    )


class PolicyBreach(BaseModel):
    """Individual policy breach grounded in a retrieved policy clause."""

    clause_id: str = Field(
        ...,
        description="Policy clause cited (e.g. 'Clause 3.1', 'Clause 4.2').",
    )
    clause_title: str = Field(
        ...,
        description="Title of the cited policy clause.",
    )
    verbatim_quote: str = Field(
        ...,
        description="Short verbatim quote from the policy returned by retrieve_policy.",
    )
    category: str = Field(
        ...,
        description="Category of breach (e.g. 'SELF_APPROVAL', 'SPLIT_PAYMENTS', 'APPROVAL_LIMIT').",
    )
    flagged_entry_ids: list[str] = Field(
        default_factory=list,
        description="Entry IDs violating this clause.",
    )
    financial_exposure_inr: float | None = Field(
        default=None,
        description="Monetary exposure in INR.",
    )
    details: str = Field(
        ...,
        description="Detailed explanation of the policy violation.",
    )


class PolicyFindings(BaseModel):
    """Structured policy compliance findings generated by policy_agent.

    Grounded against corporate SOP clauses via retrieve_policy.
    """

    total_breaches: int = Field(
        ...,
        description="Total count of distinct policy breach categories.",
    )
    self_approved_count: int = Field(
        ...,
        description="Count of self-approved transactions (Clause 3.1).",
    )
    self_approved_entry_ids: list[str] = Field(
        default_factory=list,
        description="Entry IDs violating Clause 3.1 (posted_by == approved_by).",
    )
    self_approved_total_inr: float | None = Field(
        default=None,
        description="Total INR value of self-approved transactions.",
    )
    split_payment_group_count: int = Field(
        ...,
        description="Count of split-payment structuring clusters detected (Clause 4.2).",
    )
    split_payment_entry_ids: list[str] = Field(
        default_factory=list,
        description="Entry IDs involved in split payment structuring.",
    )
    split_payment_total_inr: float | None = Field(
        default=None,
        description="Total INR value across split payment clusters.",
    )
    breaches: list[PolicyBreach] = Field(
        default_factory=list,
        description="Detailed list of grounded policy breaches.",
    )
    flagged_ids: list[str] = Field(
        default_factory=list,
        description="Combined list of all unique flagged entry IDs.",
    )
    notes: str = Field(
        ...,
        description="Executive compliance narrative citing policy clauses and verbatim rules.",
    )

